from PIL import Image; import numpy as np, json, math; from pathlib import Path
out=Path(__file__).parent; rows=json.loads((out/'e2-literal-samples.json').read_text())['rows']; native=np.asarray(Image.open('docs/parity/evidence/original/third-baseline-settled-20261025/static-0.png')); final=np.asarray(Image.open('docs/parity/evidence/web-production-candidate-v6/static/800x600-dpr1/third_puzzle/end.png')); textures={i:np.asarray(Image.open('src/assets/textures/wall_main_'+str(i)+'.png')) for i in [7,34,26]}
alpha=lambda r,x,y:(lambda u,v:sum(textures[r['tile']][min(199,max(0,math.floor(v)+dy)),min(199,max(0,math.floor(u)+dx)),3]*(1-(u-math.floor(u)) if dx==0 else u-math.floor(u))*(1-(v-math.floor(v)) if dy==0 else v-math.floor(v)) for dy in [0,1] for dx in [0,1]))((x+.5-r['rect'][0])*200/r['rect'][2]-.5,(y+.5-r['rect'][1])*200/r['rect'][3]-.5)
result=[{'pixel':r['pixel'],'zero_alpha_neighbors':sorted([{'xy':[r['pixel'][0]+dx,r['pixel'][1]+dy],'distance2':dx*dx+dy*dy,'native':native[r['pixel'][1]+dy,r['pixel'][0]+dx].tolist(),'final':final[r['pixel'][1]+dy,r['pixel'][0]+dx].tolist()} for dy in range(-3,4) for dx in range(-3,4) if r['rect'][0]<=r['pixel'][0]+dx<r['rect'][0]+r['rect'][2] and r['rect'][1]<=r['pixel'][1]+dy<r['rect'][1]+r['rect'][3] and alpha(r,r['pixel'][0]+dx,r['pixel'][1]+dy)==0],key=lambda p:(p['distance2'],p['xy'][1],p['xy'][0]))} for r in rows]
(out/'e3-local-underlay.json').write_text(json.dumps(result,indent=2),encoding='utf8'); print(json.dumps([{'pixel':r['pixel'],'nearest':r['zero_alpha_neighbors'][0] if r['zero_alpha_neighbors'] else None,'native_range':sorted(set(p['native'][0] for p in r['zero_alpha_neighbors']))} for r in result]))
